# Generated by forge. The installed packages ty is told to check as Any (SPECS §15.2):
# those that ship no typing (PEP 561: no py.typed, no .pyi, no <name>-stubs installed).
# ty infers such a package's types from its source, where mypy treats it as Any; on a
# library with runtime magic (SQLAlchemy 1.x declarative columns) that gives errors on
# correct code. Run by forge_ty_untyped (types.sh) as
#   uvx --python <py> --from ty==<pin> python untyped_python.py <root> <X.Y> <site-dir>...
# with the site-packages directories of the environment ty checks the project with, in
# import order. Prints:
#   watch <dir>    each directory the answer depends on (the site-packages directories
#                  and ty's first-party search roots): a change there recomputes it
#   <module>       each untyped top-level module, or namespace package portion (a.b)
# A module ty resolves without that environment is left out: one of the standard
# library stubs ty bundles (typing_extensions, a backport named like the module it
# backports) or the project's own code (a first-party package an installed distribution
# shadows). Which ones those are is asked from the pinned ty itself, not listed here.
# Standard library only.
import os
import re
import subprocess
import sys
import tempfile

try:
    import tomllib
except ImportError:  # the engine's Python is 3.12; never on another
    tomllib = None

ROOT = sys.argv[1]
VERSION = sys.argv[2]
SITES = [s for s in sys.argv[3:] if os.path.isdir(s)]
TY = os.path.join(os.path.dirname(sys.executable), "ty")
SKIP_SUFFIXES = (".dist-info", ".egg-info", ".data", ".pth", ".egg-link", ".egg", "-stubs")
EXT = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)\..*\.(so|pyd)$|^([A-Za-z_][A-Za-z0-9_]*)\.(so|pyd)$")


def has_init(d):
    return os.path.isfile(os.path.join(d, "__init__.py")) or os.path.isfile(os.path.join(d, "__init__.pyi"))


def ships_typing(d):
    """A package directory with py.typed, or with a .pyi anywhere in it."""
    if os.path.isfile(os.path.join(d, "py.typed")):
        return True
    for _dirpath, dirnames, filenames in os.walk(d):
        dirnames[:] = [n for n in dirnames if n != "__pycache__"]
        if "py.typed" in filenames or any(f.endswith(".pyi") for f in filenames):
            return True
    return False


def stubbed(dotted):
    """A stub-only package (<top>-stubs, PEP 561) covers the module in some site directory."""
    top, _, rest = dotted.partition(".")
    for site in SITES:
        base = os.path.join(site, top + "-stubs", *rest.split(".")) if rest else os.path.join(site, top + "-stubs")
        if os.path.isdir(base) or os.path.isfile(base + ".pyi"):
            return True
    return False


def units(site, prefix="", depth=0):
    """(dotted name, typed) for each module of a site directory; namespace packages by portion."""
    try:
        entries = sorted(os.listdir(site))
    except OSError:
        return
    for entry in entries:
        path = os.path.join(site, entry)
        if entry.startswith("__") or entry.endswith(SKIP_SUFFIXES):
            continue
        if os.path.isdir(path):
            if not entry.isidentifier():
                continue
            name = prefix + entry
            if has_init(path):
                yield name, ships_typing(path) or stubbed(name)
            elif depth < 2:
                # a namespace package: each portion is its own distribution's
                if os.path.isfile(os.path.join(path, "py.typed")):
                    yield name, True
                else:
                    yield from units(path, name + ".", depth + 1)
        elif entry.endswith(".py") and entry[:-3].isidentifier():
            name = prefix + entry[:-3]
            yield name, os.path.isfile(path + "i") or stubbed(name)
        elif entry.endswith(".pyi") and entry[:-4].isidentifier():
            yield prefix + entry[:-4], True
        else:
            m = EXT.match(entry)
            if m:
                stem = m.group(1) or m.group(3)
                name = prefix + stem
                yield name, os.path.isfile(os.path.join(site, stem + ".pyi")) or stubbed(name)


def ty_config():
    """The project's ty configuration ([tool.ty] in pyproject.toml, or ty.toml)."""
    for f, key in (("ty.toml", None), ("pyproject.toml", "tool")):
        try:
            with open(os.path.join(ROOT, f), "rb") as fh:
                data = tomllib.load(fh) if tomllib else {}
        except (OSError, ValueError):
            continue
        if key is None:
            return data, {}
        if "ty" in data.get("tool", {}):
            return data["tool"]["ty"], data.get("project", {})
        return {}, data.get("project", {})
    return {}, {}


def roots(config):
    """ty's first-party search roots: environment.root, else its layout detection's candidates."""
    configured = (config.get("environment") or {}).get("root") or (config.get("src") or {}).get("root")
    if isinstance(configured, str):
        configured = [configured]
    names = configured if isinstance(configured, list) and configured else [".", "src", "python", "tests"]
    return [os.path.normpath(os.path.join(ROOT, n)) for n in names]


def resolved_without_environment(names, config, project):
    """The names the pinned ty resolves with no site-packages at all: its bundled standard
    library stubs and the project's own code. Asked from ty: each name is imported and
    revealed in a probe file checked with the project's configuration and an empty
    environment; a resolved one reveals <module '…'>."""
    if not names:
        return set()
    with tempfile.TemporaryDirectory(prefix="forge-untyped-") as tmp:
        env = os.path.join(tmp, "env")
        os.makedirs(os.path.join(env, "lib", "python" + VERSION, "site-packages"))
        probe = os.path.join(tmp, "probe.py")
        with open(probe, "w") as fh:
            fh.write("from typing import reveal_type\n")
            for i, n in enumerate(names):
                fh.write("import %s as _m%d; reveal_type(_m%d)\n" % (n, i, i))
        args = [TY, "check", "--project", ROOT, "--python", env, "--output-format", "concise", "--exit-zero"]
        # the version ty would use: the project's (its config, requires-python), else the environment's
        if not (config.get("environment") or {}).get("python-version") and not project.get("requires-python"):
            args += ["--python-version", VERSION]
        out = subprocess.run(args + [probe], cwd=ROOT, capture_output=True, text=True, timeout=120)
        if out.returncode != 0:
            raise SystemExit("skipped: ty could not run the probe: %s" % (out.stderr.strip().splitlines() or [""])[0])
    found = set()
    for line in out.stdout.splitlines():
        m = re.match(r".*probe\.py:(\d+):\d+: info\[revealed-type\] Revealed type: `<module '", line)
        if m:
            i = int(m.group(1)) - 2
            if 0 <= i < len(names):
                found.add(names[i])
    return found


def main():
    config, project = ty_config()
    seen = {}
    for site in SITES:
        for name, typed in units(site):
            seen.setdefault(name, typed)
    untyped = sorted(n for n, typed in seen.items() if not typed)
    elsewhere = resolved_without_environment(untyped, config, project)
    keep = [n for n in untyped if n not in elsewhere]
    for d in SITES + roots(config):
        print("watch " + d)
    for n in keep:
        print(n)


main()
